const TODAYD=new Date(2026,10,25);
function dd(s){if(!s||s==='—')return null;const [d,m]=s.split('.').map(Number);return new Date(2026,m-1,d)}
function dueOf(i){const s=dd(INV[i][6]);if(!s)return null;const d=new Date(s);d.setDate(d.getDate()+INV[i][4]);return d}
const fd=d=>d?String(d.getDate()).padStart(2,'0')+'.'+String(d.getMonth()+1).padStart(2,'0'):'—';
function overdue(i){const d=dueOf(i);return d?Math.round((TODAYD-d)/864e5):0}
const debts=()=>INV.map((x,i)=>i).filter(i=>INV[i][5]==='shipped'&&INV[i][4]>0);
const debtSum=()=>debts().reduce((a,i)=>a+INV[i][3],0);

// ---------- расчёты для аналитики ----------
const openDeals=()=>DEALS.filter(d=>d[4]<7);
const kpOut=()=>DEALS.filter(d=>d[4]>=2&&d[4]<=4);
const stuckList=()=>DEALS.filter(d=>(d[4]===2||d[4]===3)&&d[8]>=14).sort((a,b)=>b[8]-a[8]);
const backList=()=>DEALS.filter(d=>CL[d[1]][8]>150||d[7]==='rep'||[3,8].indexOf(d[1])>=0).filter(d=>d[4]<7);
const sumBy=f=>DEALS.filter(f).reduce((a,d)=>a+d[5],0);

// ================= ЭКРАНЫ =================
