// ================= ДЕЙСТВИЯ =================
function openDeal(id){const d=dealBy(id);if(!d)return;const c=CL[d[1]];
 openM(`${d[0]} · ${esc(c[0])}`,`${esc(d[2])} · ${ST[d[4]]}`,stepsBar(d[4])+`<div class="kv"><span>Сумма</span><b class="num">${d[5]?tg(d[5]):'после КП'}</b></div><div class="kv"><span>Тип клиента</span><b>${cType(d[1])}${c[3]==='dist'?' −'+c[5]+'%':''}</b></div><div class="kv"><span>Оплата</span><b>${terms(c[4])}</b></div><div class="kv"><span>Источник</span><b>${SRC[d[7]]}</b></div><div class="kv"><span>Менеджер</span><b>${MGR[d[3]]}</b></div><div class="kv"><span>В этапе</span><b>${d[6]} дн.</b></div><div class="btns"><button class="bt" onclick="stageNext('${d[0]}');closeM()">Следующий этап →</button><button class="bt o" onclick="closeM();openClient(${d[1]})">Карточка компании</button><button class="bt o" onclick="closeM();kpFor(${d[1]})">КП</button></div>`)}
function stageNext(id){const d=dealBy(id);if(!d)return;if(d[4]>=7){toast('Сделка уже оплачена — она в истории клиента, а повтор система предложит через 6 месяцев.');return}d[4]++;d[6]=0;if(d[4]===2||d[4]===3)d[8]=0;
 if(d[4]===3){addTask('Напомнить по КП +7 дн.',d[0],'+7 дн.',d[3],true)}
 build();toast(`${d[0]} → <b>${ST[d[4]]}</b>.${d[4]===3?' Поставлены напоминания на 7, 14 и 30 дней.':d[4]===5?' Счёт сформирован из последней версии КП.':d[4]===6?' Позиции списываются со склада.':''}`)}
function remind(id){REMIND[id]=(REMIND[id]||0)+1;const d=dealBy(id);if(d)d[6]=0;build();toast(`Напоминание по ${id} ушло в WhatsApp контакту ${d?esc(CL[d[1]][6][0][0]):''}: «Добрый день! Есть ли решение по нашему КП? Готовы ответить на вопросы и держим цену до 31.12». Следующее — через 7 дней.`)}
function remindAll(){stuckList().forEach(d=>REMIND[d[0]]=(REMIND[d[0]]||0)+1);build();toast(`Отправлено ${stuckList().length} напоминаний шаблоном. Ответы придут в WhatsApp и попадут в сделки.`)}
function openClient(i){CLsel=i;if(!allowed('client')){toast('Карточка компании недоступна этой роли.');return}cur='client';build();window.scrollTo(0,0)}
function newDeal(){const id='D-'+(140+DEALS.length-16);DEALS.push([id,7,'Цех розлива: 14 линий (из WhatsApp)',2,0,0,0,'wa',-1]);build();toast(`Создана сделка <b>${id}</b> из сообщения Самал Нурпеисовой. Переписка прикреплена.`)}
function newDealFrom(co){const id='D-'+(140+DEALS.length-16);DEALS.push([id,co,'Новый запрос · '+CL[co][0],role==='Менеджер'?1:0,0,0,0,'wa',-1]);toast(`Сделка <b>${id}</b> создана, переписка и письма прикреплены к ней.`);build()}
function tgTask(i){TASKS[i].done=!TASKS[i].done;build()}
function addTaskQ(){addTask('Позвонить снабжению: уточнить бюджет на 2027','D-118','29.11',role==='Менеджер'?1:0,false);build();toast('Задача добавлена и появится в пульте и на телефоне.')}
function kpQ(i,v){KP.lines[i][1]=Math.max(0,parseInt(v)||0);build()}
function kpDel(i){KP.lines.splice(i,1);build()}
function kpAdd(s){const f=KP.lines.find(l=>l[0]===s);if(f)f[1]++;else KP.lines.push([s,1]);build();toast(`${s} добавлен в КП.`)}
function kpFor(i){KP.cl=i;const d=DEALS.find(x=>x[1]===i);KP.deal=d?d[0]:'новая';if(!allowed('kp')){toast('Конструктор КП недоступен этой роли.');return}cur='kp';build();window.scrollTo(0,0);toast(`КП для <b>${esc(CL[i][0])}</b>: ${CL[i][3]==='dist'?'дилерская цена −'+CL[i][5]+'%':'цена конечного пользователя'}.`)}
function kpNewVer(){KP.ver=KPV.length+1;KPV.push({v:KP.ver,d:'25.11.2026',who:role==='Менеджер'?'Данияр С.':'Абзал Ж.',sum:kpSum(),disc:KP.disc,note:'Новая версия после торга'+(KP.disc?': скидка '+KP.disc+'%':'')});const d=dealBy('D-118');if(d&&KP.deal==='D-118'){d[5]=kpSum();d[4]=Math.max(d[4],4)}build();toast(`Сохранена версия <b>v${KP.ver}</b> на ${tg(kpSum())}. Прошлые версии остались в истории.`)}
function kpSend(ch){KP.sent=true;const d=dealBy(KP.deal);if(d){d[5]=kpSum();d[4]=Math.max(d[4],3);d[8]=0;d[6]=0}
 KP.lines.forEach(l=>{if(PR[SKU[l[0]]][2]!=='S')RES[l[0]]=Math.max(RES[l[0]]||0,l[1])});
 addTask('КП: напомнить +7 дн.',KP.deal,'+7 дн.',d?d[3]:0,true);addTask('КП: напомнить +14 дн.',KP.deal,'+14 дн.',d?d[3]:0,true);addTask('КП: позвонить +30 дн.',KP.deal,'+30 дн.',d?d[3]:0,true);
 build();toast(`КП v${KP.ver} на <b>${tg(kpSum())}</b> отправлено ${ch==='wa'?'в WhatsApp':'на почту'} ${esc(CL[KP.cl][6][0][0])}. Сделка — «На согласовании», позиции в резерве, напоминания: 7, 14, 30 дней.`)}
function kpDoc(lines,disc,v){const c=CL[KP.cl];const pr=s=>{const p=PR[SKU[s]];const b=c[3]==='dist'?p[3]*(1-c[5]/100):p[3];return Math.round(b*(1-disc/100))};const sum=lines.reduce((a,l)=>a+pr(l[0])*l[1],0);
 return `<div class="doc"><div class="dh"><div><h4>Коммерческое предложение № КП-${KP.deal.replace('D-','')}-v${v}</h4><small>от 25.11.2026 · действительно 30 дней</small></div><div style="text-align:right"><b>ТОО «СТОП-ЛОК»</b><br><small>системы блокировки LOTO</small></div></div><p><b>Кому:</b> ${esc(c[0])}, ${esc(c[6][0][0])} (${esc(c[6][0][1])})</p><p style="margin:6px 0 10px"><b>Предмет:</b> оснащение средствами блокировки и маркировки (LOTO) по результатам обследования.</p>`
 +tbl(['№','Артикул','Наименование','>Кол.','>Цена','>Сумма'],lines.map((l,i)=>`<tr><td>${i+1}</td><td class="mono">${l[0]}</td><td>${esc(PR[SKU[l[0]]][1])}</td><td class="r num">${l[1]}</td><td class="r num">${fmt(pr(l[0]))}</td><td class="r num">${fmt(pr(l[0])*l[1])}</td></tr>`))
 +`<div class="kv"><span>Итого, без НДС</span><b class="num">${tg(sum)}</b></div><div class="kv"><span>Оплата</span><b>${terms(c[4])}</b></div><div class="kv"><span>Срок поставки</span><b>со склада 3–5 дней, под заказ 30–45 дней</b></div><p class="note">Приложение 1: схема точек блокировки по участкам. Приложение 2: сертификаты на диэлектрические замки.</p></div>`}
function kpPdf(){openM('PDF-предпросмотр','Так клиент увидит КП. Кнопка «Скачать» сохраняет PDF с приложениями.',kpDoc(KP.lines,KP.disc,KP.ver)+`<div class="btns"><button class="bt" onclick="toast('PDF сохранён и прикреплён к сделке ${KP.deal}.')">Скачать PDF</button></div>`)}
function kpPdfV(i){const v=KPV[i];openM(`КП v${v.v} · ${v.d}`,esc(v.note),kpDoc(v.v===1?KP.lines.filter(l=>l[0]!=='SL-S704'):KP.lines,v.disc,v.v))}
function dDisc(i,d){CL[i][5]=Math.max(10,Math.min(30,CL[i][5]+d));build();toast(`Скидка ${esc(CL[i][0])}: <b>${CL[i][5]}%</b> — новые КП пойдут по ней.`)}
function waOpen(co){const i=CHATS.findIndex(c=>c.co===co);if(i<0){CHATS.unshift({co,n:CL[co][6][0][0],u:0,msgs:[['s','Новый чат · история компании подтянута','']]});waC=0}else waC=i;if(!allowed('wa')){toast('Переписка недоступна этой роли.');return}cur='wa';build()}
function waSend(){const el=document.getElementById('wain'),v=(el&&el.value.trim())||'Добрый день! Подскажите, есть ли решение по нашему предложению?';CHATS[waC].msgs.push([1,v,'сейчас']);build();toast('Сообщение ушло в WhatsApp клиента и сохранено в карточке.')}
function waTpl(){const el=document.getElementById('wain');if(el)el.value='Добрый день! Направляю КП с приложением. Цена действует 30 дней, склад в Алматы, отгрузка 3–5 дней.';toast('Шаблон подставлен — можно поправить и отправить.')}
function mailTask(){const m=MAILS[mSel];addTask('Ответить: '+m.s,(DEALS.find(d=>d[1]===m.co)||['—'])[0],'сегодня',role==='Менеджер'?1:0,false);build();toast('Из письма создана задача на сегодня.')}
function mailLink(){MAILS[mSel].ln=true;build();toast(`Письмо прикреплено к карточке «${esc(CL[MAILS[mSel].co][0])}».`)}
function playRec(i){toast(`▶ Запись звонка ${esc(CALLS[i][1])}, ${CALLS[i][3]}. В демо звук не воспроизводится — в системе плеер прямо в карточке.`)}
function shipInv(i){const x=INV[i];if(x[5]!=='issued'){toast('Счёт уже отгружен.');return}x[7].forEach(l=>{const k=SKU[l[0]];if(k!==undefined){PR[k][5]=Math.max(0,PR[k][5]-l[1]);if(RES[l[0]])RES[l[0]]=Math.max(0,RES[l[0]]-l[1])}});x[5]=x[4]?'shipped':'paid';x[6]='25.11';const d=dealBy(x[1]);if(d)d[4]=Math.max(d[4],6);build();toast(`${x[0]} отгружен: товар списан со склада${x[4]?`, долг ${tg(x[3])} до ${fd(dueOf(i))} — в дебиторке`:''}.`)}
function payInv(i){const x=INV[i];if(x[5]==='paid'){toast('Счёт уже оплачен.');return}const pre=x[5]==='issued';if(pre){x[7].forEach(l=>{const k=SKU[l[0]];if(k!==undefined)PR[k][5]=Math.max(0,PR[k][5]-l[1])});x[6]='25.11'}x[5]='paid';const d=dealBy(x[1]);if(d)d[4]=7;build();toast(`${x[0]}: оплата ${tg(x[3])} отмечена.${pre?' Предоплата пришла — товар отгружен и списан.':' Долг закрыт.'} Повторная продажа будет предложена через 6 месяцев.`)}
function reviveKP(co){const d=DEALS.find(x=>x[1]===co);if(d){d[4]=2;d[5]=1302000;d[8]=0}KP.cl=co;KP.deal=d?d[0]:'новая';build();toast('КП-071 из мая поднято как новая версия по текущим ценам: 1 302 000 ₸. Осталось проверить и отправить.')}
function repKP(co){KP.cl=co;KP.lines=[['SL-T501',20],['SL-T505',10],['SL-T507',5],['SL-L301',20]];KP.deal='повтор';if(!allowed('kp')){toast('КП недоступно этой роли.');return}cur='kp';build();toast(`КП повтора для <b>${esc(CL[co][0])}</b>: расходники по прошлой закупке.`)}

// ================= КАРКАС =================
function renderRoles(){document.getElementById('roles').innerHTML=Object.entries(ROLES).map(([k,v])=>`<div class="role" onclick="enter('${esc(k)}')"><div class="rav">${v.av}</div><div><b>${esc(k)}</b><span>${esc(v.n)} · ${esc(v.note)}</span></div></div>`).join('');document.getElementById('rsel').innerHTML=Object.keys(ROLES).map(k=>`<option>${esc(k)}</option>`).join('')}
const allowed=k=>ROLES[role].s.indexOf(k)>=0;
function enter(k){role=ROLES[k]?k:'Собственник';document.getElementById('gate').classList.add('hidden');document.getElementById('app').classList.remove('hidden');document.getElementById('rsel').value=role;document.getElementById('me').textContent=ROLES[role].av;if(!allowed(cur))cur=ROLES[role].s[0];build()}
function switchRole(k){role=k;document.getElementById('me').textContent=ROLES[role].av;document.getElementById('rsel').value=role;if(!allowed(cur))cur=ROLES[role].s[0];build();toast(`Роль <b>${esc(role)}</b>: ${esc(ROLES[role].note)}.`)}
function goSec(k){const S=SEC.find(x=>x.k===k);const f=S.sub.find(x=>allowed(x[0]));if(f)go(f[0])}
function badge(k){if(k==='sales')return stuckList().length;if(k==='com')return CHATS.reduce((a,c)=>a+c.u,0)+MAILS.filter(m=>!m.rd).length;if(k==='money')return debts().filter(i=>overdue(i)>0).length;return 0}
function buildRail(){const vis=SEC.filter(s=>s.sub.some(x=>allowed(x[0])));document.getElementById('rail').innerHTML=vis.map((s,i)=>{const b=badge(s.k);return `<div class="ri ${s.k===SECOF[cur]?'on':''}" onclick="goSec('${s.k}')"><span>${String(i+1).padStart(2,'0')}</span>${s.n}${b?`<i>${b}</i>`:''}</div>`}).join('');
 const S=SEC.find(x=>x.k===SECOF[cur]);document.getElementById('tabs').innerHTML=S.sub.filter(x=>allowed(x[0])).map(x=>`<a class="${x[0]===cur?'on':''}" onclick="go('${x[0]}')">${esc(x[1])}</a>`).join('');
 document.getElementById('crumb').innerHTML=`${esc(S.n)} / <b>${esc(SUBN[cur])}</b> · ${esc(role)}, ${esc(ROLES[role].n)}`}
function build(){if(!allowed(cur))cur=ROLES[role].s[0];buildRail();document.getElementById('ttl').textContent=cur==='client'?CL[CLsel][0]:SUBN[cur];document.getElementById('content').innerHTML=SC[cur]();try{history.replaceState(null,'','?s='+cur)}catch(e){}}
function go(k){if(!allowed(k)){toast('Этой роли раздел недоступен — так работают права. Переключите роль.');return}cur=k;build();window.scrollTo(0,0)}
function openM(t,s,b){document.getElementById('mt').innerHTML=t;document.getElementById('ms').innerHTML=s;document.getElementById('mbody').innerHTML=b;document.getElementById('mbg').classList.add('show')}
function closeM(){document.getElementById('mbg').classList.remove('show')}
let tt=null;function toast(m){const t=document.getElementById('toast');t.innerHTML=m;t.classList.add('show');clearTimeout(tt);tt=setTimeout(()=>t.classList.remove('show'),6500)}
const TOUR=[['how','1 · Вся цепочка сделки на одном экране.'],['wa','2 · Заявка в WhatsApp — сразу в карточку компании.'],['client','3 · Компания: инженер ОТ, снабжение, закуп и вся история.'],['deal','4 · Консультация: что блокируем на заводе.'],['kp','5 · КП из каталога: цена конечника или дилера, PDF.'],['stuck','6 · Зависшие КП: деньги на столе и кнопка «Напомнить».'],['kpver','7 · Торг: версии КП.'],['ship','8 · Счёт и отгрузка со списанием.'],['debt','9 · Отсрочка 30/60 — дебиторка с датами.'],['back','10 · Клиент вернулся через полгода — всё видно.'],['repeat','11 · Повторная закупка бирок и замков.'],['dash','12 · Пульт Абзала.']];
let ti=-1,tRun=false;function tour(){if(tRun){tRun=false;return}tRun=true;ti=-1;step()}
function step(){if(!tRun)return;ti++;if(ti>=TOUR.length){tRun=false;toast('Сценарий закончен — всё кликается.');return}const [k,m]=TOUR[ti];if(!allowed(k))switchRole('Собственник');if(k==='client')CLsel=0;cur=k;build();window.scrollTo(0,0);toast('<b>'+m+'</b>');setTimeout(step,5200)}
function stopTour(){tRun=false}
(function(){renderRoles();document.getElementById('rsel').addEventListener('change',e=>switchRole(e.target.value));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeM();tRun=false}});
 let q='';try{q=new URLSearchParams(location.search).get('s')||''}catch(e){}
 if(q&&SECOF[q]){const r=Object.keys(ROLES).find(k=>ROLES[k].s.indexOf(q)>=0);if(r){cur=q;enter(r)}}})();
